"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[73618],{3331:(e,i,a)=>{a.d(i,{R:()=>r,x:()=>l});var o=a(36672);const n={},t=o.createContext(n);function r(e){const i=o.useContext(t);return o.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function l(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),o.createElement(t.Provider,{value:i},e.children)}},9553:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>s,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"2023/04/13","title":"2023-04-13","description":"Semaphore: Una tastiera per tutto il corpo","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/04/13.md","sourceDirName":"2023/04","slug":"/2023/04/13","permalink":"/it/2023/04/13","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/04/13.md","tags":[],"version":"current","frontMatter":{"localized_date":"13 aprile 2023","top_news":"Semaphore: Una tastiera per tutto il corpo"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-14","permalink":"/it/2023/04/14"},"next":{"title":"2023-04-12","permalink":"/it/2023/04/12"}}');var n=a(23420),t=a(3331);const r={localized_date:"13 aprile 2023",top_news:"Semaphore: Una tastiera per tutto il corpo"},l="2023-04-13",s={},c=[{value:"Semaphore: Una tastiera per tutto il corpo",id:"semaphore-una-tastiera-per-tutto-il-corpo",level:2},{value:"Mostra Ricerche sul web per sviluppatori basate su GPT-4",id:"mostra-ricerche-sul-web-per-sviluppatori-basate-su-gpt-4",level:2},{value:"Sostituire i miei migliori amici con un LLM addestrato su 500k messaggi di chat di gruppo",id:"sostituire-i-miei-migliori-amici-con-un-llm-addestrato-su-500k-messaggi-di-chat-di-gruppo",level:2},{value:"La NPR abbandona Twitter dopo essere stata etichettata come &quot;media affiliato allo Stato&quot;.",id:"la-npr-abbandona-twitter-dopo-essere-stata-etichettata-come-media-affiliato-allo-stato",level:2},{value:"Licenziamenti di massa e capi assenti creano una crisi di morale a Meta",id:"licenziamenti-di-massa-e-capi-assenti-creano-una-crisi-di-morale-a-meta",level:2},{value:"Hetzner presenta i server cloud ARM64",id:"hetzner-presenta-i-server-cloud-arm64",level:2},{value:"Il nuovo direttore della NASA giura su &quot;Pale Blue Dot&quot; di Carl Sagan invece che sulla Bibbia",id:"il-nuovo-direttore-della-nasa-giura-su-pale-blue-dot-di-carl-sagan-invece-che-sulla-bibbia",level:2},{value:"Intel Foundry Services e Arm annunciano una collaborazione per la progettazione di SoC",id:"intel-foundry-services-e-arm-annunciano-una-collaborazione-per-la-progettazione-di-soc",level:2},{value:"Un giocatore di EVE Online usa una regola oscura per mettere a segno il pi\xf9 grande furto nella storia del gioco",id:"un-giocatore-di-eve-online-usa-una-regola-oscura-per-mettere-a-segno-il-pi\xf9-grande-furto-nella-storia-del-gioco",level:2},{value:"I thread virtuali arrivano in JDK 21, inaugurando una nuova era della concorrenza",id:"i-thread-virtuali-arrivano-in-jdk-21-inaugurando-una-nuova-era-della-concorrenza",level:2}];function d(e){const i={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(i.header,{children:(0,n.jsx)(i.h1,{id:"2023-04-13",children:"2023-04-13"})}),"\n",(0,n.jsx)(i.h2,{id:"semaphore-una-tastiera-per-tutto-il-corpo",children:"Semaphore: Una tastiera per tutto il corpo"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://github.com/everythingishacked/Semaphore",children:"Originale"}),".\nSemaphore \xe8 una tastiera a corpo intero che utilizza OpenCV e il rilevamento della posa di MediaPipe per rilevare i punti di riferimento del corpo dall'input video, calcolare le differenze relative e tradurle in tasti e comandi inviati tramite tastiera. L'input principale consiste nel \"digitare\" lettere, cifre e simboli tramite semaforo a bandiera estendendo entrambe le braccia a varie angolazioni, con altri gesti modificatori inclusi per funzioni quali shift, backspace e tasti freccia. Funziona sull'ultimo MacOS e si pu\xf2 accedere al terminale con l'uso di una libreria di tastiera personalizzata."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35536550",children:"Discussion Service"}),".\nUn sistema di tastiera chiamato Semaphore, che utilizza gesti fisici, ha ricevuto un feedback positivo dagli utenti di Discussion Service e ha implicazioni per i lavoratori remoti che vogliono combinare l'esercizio fisico con la programmazione. Gli utenti parlano della possibilit\xe0 di combinare Semaphore con la stenografia, le note musicali, gli esercizi di yoga e la programmazione, e alcuni sottolineano il potenziale di aumento dell'efficienza grazie all'aggiunta di funzioni come il completamento automatico."]}),"\n",(0,n.jsx)(i.h2,{id:"mostra-ricerche-sul-web-per-sviluppatori-basate-su-gpt-4",children:"Mostra Ricerche sul web per sviluppatori basate su GPT-4"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.phind.com",children:"Originale"}),".\nIl sito web \"phind.com\" \xe8 attualmente inaccessibile, in quanto utilizza un servizio di sicurezza per proteggersi dagli attacchi online che potrebbero essere stati scatenati da alcune azioni, come l'invio di una determinata parola o frase, un comando SQL o dati malformati. Per risolvere il problema, gli utenti possono inviare un'e-mail al proprietario del sito, indicando i dettagli di ci\xf2 che stavano facendo quando si \xe8 verificato il blocco e il Cloudflare Ray ID che si trova in fondo alla pagina."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35543668",children:"Discussion Service"}),".\nIl motore di ricerca GPT-4 di Phind.com offre risposte di codifica precise e spiegazioni dettagliate attraverso filtri personalizzati; sono stati esplorati modelli di condivisione dei ricavi per i produttori di contenuti, anche se ci sono preoccupazioni per i costi di modellazione; gli utenti hanno elogiato il servizio per la chiarezza delle informazioni, l'efficienza e le preziose informazioni supplementari, anche se sono stati rilevati alcuni problemi di accuratezza delle query. Alcuni utenti hanno criticato la capacit\xe0 di GPT-4 di risolvere i problemi e ne hanno messo in dubbio l'accuratezza e la pertinenza, ma il team di Phind ha risposto rilasciando una nuova versione con la funzione Expert mode."]}),"\n",(0,n.jsx)(i.h2,{id:"sostituire-i-miei-migliori-amici-con-un-llm-addestrato-su-500k-messaggi-di-chat-di-gruppo",children:"Sostituire i miei migliori amici con un LLM addestrato su 500k messaggi di chat di gruppo"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.izzy.co/blogs/robo-boys.html",children:"Originale"}),".\nUn LLM \xe8 stato addestrato sui messaggi non censurati delle chat di gruppo dell'epoca universitaria di Izzy Miller, ottenendo conversazioni migliori con i suoi migliori amici. Il dataset era composto da 500k messaggi e Miller lo ha sessionato per facilitare la modellazione. Il modello risultante ha generato intere conversazioni, catturando l'essenza contestuale della chat di gruppo. L'articolo spiega come convertire i pesi LLaMA in un formato compatibile con la libreria Transformers utilizzando la codifica Python, compresa l'importanza di un corretto approvvigionamento di spazio su disco."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35540154",children:"Discussion Service"}),".\nAlcuni utenti di Discussion Service esprimono preoccupazione per le implicazioni etiche della creazione di copie digitali di individui utilizzando dati personali, mentre altri sostengono che le leggi esistenti e la pressione morale/sociale sono ancora valide. I critici mettono in guardia da potenziali applicazioni nefaste della tecnologia LLM da parte di regimi autocratici o per scopi di lucro. Sono emersi dibattiti divisivi sulla tecnologia AI, con preoccupazioni per il suo impatto non testato sulla privacy e iper-scetticismo sulla sua efficacia. Vi sono controversie sull'uso dei chatbot dell'IA e sul loro potenziale di sostituzione dei legami umani, nonch\xe9 preoccupazioni etiche sugli strumenti di completamento del testo che consentono di creare simulazioni digitali di persone care scomparse."]}),"\n",(0,n.jsx)(i.h2,{id:"la-npr-abbandona-twitter-dopo-essere-stata-etichettata-come-media-affiliato-allo-stato",children:'La NPR abbandona Twitter dopo essere stata etichettata come "media affiliato allo Stato".'}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.wbur.org/npr/1169269161/npr-leaves-twitter-government-funded-media-label",children:"Originale"}),'.\nLa NPR ha interrotto la propria attivit\xe0 su Twitter dopo essere stata etichettata da Twitter come "media affiliati allo Stato", un\'etichetta che la NPR ritiene imprecisa e fuorviante. Questa decisione protegge la credibilit\xe0 della NPR e garantisce che possa produrre giornalismo senza negativit\xe0. Elon Musk ha ammesso di aver sbagliato l\'etichetta e potrebbe cambiarla in "finanziata dallo Stato".']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35539280",children:"Discussion Service"}),".\nLa NPR \xe8 stata criticata e alla fine ha abbandonato Twitter dopo essere stata etichettata come \"media affiliato allo Stato\" a causa dei finanziamenti governativi, il che ha portato a un dibattito sui criteri di tale etichettatura e sul fatto che essa caratterizzi accuratamente la NPR come un'organizzazione di notizie con indipendenza editoriale. Alcuni utenti di Discussion Service suggeriscono che altre aziende, tra cui quelle di Elon Musk, rientrano in questa categoria a causa dei finanziamenti governativi. I commenti evidenziano anche la complessa relazione tra i media, le fonti di finanziamento e l'indipendenza editoriale, con alcuni che accusano la NPR di essere schierata a sinistra e altri che ne difendono la trasparenza e l'indipendenza."]}),"\n",(0,n.jsx)(i.h2,{id:"licenziamenti-di-massa-e-capi-assenti-creano-una-crisi-di-morale-a-meta",children:"Licenziamenti di massa e capi assenti creano una crisi di morale a Meta"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.nytimes.com/2023/04/12/technology/meta-layoffs-employees-management.html",children:"Originale"}),".\nIl morale della societ\xe0 madre di Facebook, Meta, \xe8 in calo a causa dei licenziamenti di massa e dei capi assenti, che stanno creando preoccupazione tra i lavoratori. Anche la direzione dell'azienda \xe8 messa in discussione dai dipendenti."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35537813",children:"Discussion Service"}),".\nGli esperti discutono opinioni diverse sul futuro di tecnologie all'avanguardia come l'IA generativa, la VR e le criptovalute. Mentre alcuni sostengono casi d'uso specifici dell'IA generativa e i progressi nei media generativi, vengono sollevate preoccupazioni sul suo potenziale di automatizzazione dei lavori della classe media e sull'accuratezza dei modelli di IA generativa. Le aziende guardano all'IA generativa per contribuire ad accelerare il mercato della tecnologia AR/VR, e il successo dei dispositivi di Meta Labs viene contrapposto all'incerto successo delle cuffie di Apple. Il settore delle criptovalute \xe8 visto da alcuni come una truffa per affinit\xe0, ma il Bitcoin \xe8 ancora visto in modo diverso da altri."]}),"\n",(0,n.jsx)(i.h2,{id:"hetzner-presenta-i-server-cloud-arm64",children:"Hetzner presenta i server cloud ARM64"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.hetzner.com/press-release/arm64-cloud/",children:"Originale"}),".\nIl provider tedesco di hosting e cloud Hetzner ha lanciato quattro nuovi server Hetzner Cloud basati sulla tecnologia Arm64, che rappresentano il primo utilizzo di questi processori da parte dell'azienda. I server offrono fino a 16 vCPU e si combinano con fino a 32 GB di RAM ECC e fino a 320 GB di storage basato su SSD NVMe. La nuova linea di server parte da un prezzo di 3,79 euro (4,54 dollari) al mese, con opzioni di fatturazione oraria che ridurranno i costi per i clienti."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35540084",children:"Discussion Service"}),".\nHetzner ha rilasciato server cloud ARM64 meno costosi e pi\xf9 performanti di AWS. L'infrastruttura cloud ha opinioni contrastanti: alcuni sostengono l'affidabilit\xe0 e la scalabilit\xe0, mentre altri ritengono che le configurazioni pi\xf9 semplici siano pi\xf9 affidabili e convenienti. L'offerta di Hetzner colma una lacuna per coloro che vogliono eseguire Docker senza configurare tutti i servizi, ma potrebbe non essere adatta alle aziende attente alla sicurezza a causa del controllo degli accessi fisici pi\xf9 debole. Alcuni hanno segnalato il blocco degli account a causa della rigida politica antifrode di Hetzner e ci si interroga sulla sostenibilit\xe0 dei prezzi bassi in Europa a causa degli elevati costi energetici."]}),"\n",(0,n.jsx)(i.h2,{id:"il-nuovo-direttore-della-nasa-giura-su-pale-blue-dot-di-carl-sagan-invece-che-sulla-bibbia",children:'Il nuovo direttore della NASA giura su "Pale Blue Dot" di Carl Sagan invece che sulla Bibbia'}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.independent.co.uk/space/nasa-director-carl-sagan-oath-b2317698.html",children:"Originale"}),'.\nMakenzie Lystrup, la neo-direttrice del Goddard Space Flight Center della NASA, ha prestato un giuramento non convenzionale usando il libro di Carl Sagan del 1994 "Pale Blue Dot" invece della Bibbia. Il libro dell\'astronomo si ispira alla famosa fotografia della Terra "Pale Blue Dot" scattata nel 1990 dalla sonda spaziale Voyager 1. Lystrup afferma di essere "fortemente concentrato sulla crescita della prossima generazione di innovatori". La forza lavoro del Goddard Space Flight Center \xe8 composta da 10.000 dipendenti, sia dipendenti pubblici che appaltatori, e il centro \xe8 responsabile dell\'esecuzione di un portafoglio di 4 miliardi di dollari.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35536612",children:"Discussion Service"}),".\nIl nuovo direttore della NASA ha giurato su \"Pale Blue Dot\" di Carl Sagan, scatenando un dibattito sull'efficacia dei giuramenti, sul significato dei testi sacri, sui valori personali rispetto ai testi religiosi e sul vero significato della responsabilit\xe0 personale. Alcuni sostengono che giurare su un libro che rappresenta i propri valori sia pi\xf9 appropriato, mentre altri ritengono necessaria la rappresentazione di una divinit\xe0 come garante del giuramento. Il giuramento ha un ruolo rituale ed \xe8 stato utilizzato per plasmare le societ\xe0 e la storia, ma in definitiva l'articolo non contiene informazioni nuove o interessanti per gli esperti del settore."]}),"\n",(0,n.jsx)(i.h2,{id:"intel-foundry-services-e-arm-annunciano-una-collaborazione-per-la-progettazione-di-soc",children:"Intel Foundry Services e Arm annunciano una collaborazione per la progettazione di SoC"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.intel.com/content/www/us/en/newsroom/news/intel-foundry-arm-announce-multigeneration-collaboration-leading-edge-soc-design.html",children:"Originale"}),".\nIntel Foundry Services (IFS) e Arm hanno concordato una collaborazione multigenerazionale per consentire lo sviluppo di system-on-chip (SoC) di calcolo a basso consumo per dispositivi mobili e altri settori. La collaborazione vedr\xe0 la combinazione dei processori sicuri ed efficienti dal punto di vista energetico di Arm con l'impronta produttiva di IFS, che comprende capacit\xe0 con sede negli Stati Uniti e nell'Unione Europea, e fornir\xe0 nuove tecnologie di transistor rivoluzionarie per migliorare la potenza e le prestazioni sul processo Intel 18A. Questa collaborazione consentir\xe0 una catena di fornitura globale pi\xf9 equilibrata per i clienti delle fonderie che lavorano alla progettazione di SoC mobili con core CPU basati su Arm."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35539057",children:"Discussion Service"}),".\nIntel Foundry Services collabora con Arm per la progettazione di SoC, affrontando la concorrenza di TSMC, che ha gi\xe0 collaborato con Arm. Gli utenti di Discussion Service discutono i pro e i contro di Mac Studio e lo confrontano con altre opzioni per PC, criticando i limiti del Mac per i giochi e il software CAD. L'articolo e i commenti riguardano le alternative per i dispositivi IOT e la produzione, la produzione del nodo a 2 nm di Intel e le speculazioni sulla capacit\xe0 di Intel di mantenere le promesse fatte, riconoscendo al contempo l'importanza del consumo energetico, del prezzo e della capacit\xe0 wireless nello sviluppo dei dispositivi IOT."]}),"\n",(0,n.jsx)(i.h2,{id:"un-giocatore-di-eve-online-usa-una-regola-oscura-per-mettere-a-segno-il-pi\xf9-grande-furto-nella-storia-del-gioco",children:"Un giocatore di EVE Online usa una regola oscura per mettere a segno il pi\xf9 grande furto nella storia del gioco"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.pcgamer.com/eve-online-player-uses-obscure-rule-to-pull-off-the-biggest-heist-in-the-games-history/",children:"Originale"}),'.\nUn giocatore di EVE Online ha compiuto la pi\xf9 grande rapina nella storia del gioco sfruttando la "meccanica delle azioni", ottenendo un bottino di oltre 22.300 dollari in denaro reale. Si \xe8 trattato di prendere il controllo di Event Horizon Expeditionaries utilizzando un account pulito, trasferendo le azioni e privando il portafoglio aziendale di 130 miliardi di ISK e di diverse navi, stimando il valore totale del bottino a 2,23 trilioni di ISK. Il sistema delle azioni \xe8 potenzialmente troppo facile da sfruttare, secondo un thread su Reddit del 2014, e questa strategia \xe8 stata gi\xe0 testata in passato.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35533711",children:"Discussion Service"}),".\nUn giocatore ha orchestrato una rapina di successo in EVE Online, sollevando domande sulle sue meccaniche aziendali e sui rischi di sfruttamento del gioco. La rapina \xe8 stata vista come una cosa bella e un punto di forza del gioco, ma alcuni criticano l'attenzione e le meccaniche finanziarie del gioco, tra cui il valore della valuta di gioco e il sistema di votazione aziendale."]}),"\n",(0,n.jsx)(i.h2,{id:"i-thread-virtuali-arrivano-in-jdk-21-inaugurando-una-nuova-era-della-concorrenza",children:"I thread virtuali arrivano in JDK 21, inaugurando una nuova era della concorrenza"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.infoq.com/news/2023/04/virtual-threads-arrives-jdk21/",children:"Originale"}),".\nN/A."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35535906",children:"Discussion Service"}),".\nI thread virtuali di JDK 21 riducono i thread fisici per favorire la concomitanza e la semplificazione delle applicazioni ad uso intensivo di intelligenza, ma sorgono dibattiti sulla gestione della memoria. Java viene confrontato con Go e framework come Spring, Spring Boot e Quarkus forniscono alternative a Ruby on Rails, mentre il dibattito su Java contro Go prende in considerazione le prestazioni, l'osservabilit\xe0, la solidit\xe0 dei sistemi di tipi e l'interop. L'articolo riflette sulla categoria di nicchia delle JVM e su come le diverse implementazioni possano influire sull'esperienza dell'utente, con confronti con C# e JetBrains Rider."]})]})}function u(e={}){const{wrapper:i}={...(0,t.R)(),...e.components};return i?(0,n.jsx)(i,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);